-- NEBRIN WEBSITE V7 MIGRATION
-- Ensures every standard Admin service also exists in public.services.
-- The customer form already reads all active services directly from this table.

on conflict (name) do update
set
  category = excluded.category,
  description = case when public.services.description = '' then excluded.description else public.services.description end,
  processing_time = case when public.services.processing_time = '' then excluded.processing_time else public.services.processing_time end,
  required_documents = case
    when public.services.required_documents = '[]'::jsonb then excluded.required_documents
    else public.services.required_documents
  end,
  is_active = true;
